<template>
  <div class="dt-page">

    <div class="bpm-list">
      <div class="card-container" :style="containerStyle">
        <section v-for="(mainGroup, mainIndex) in sortedCardList" :id="`bpm-${mainIndex}`" :key="mainIndex" class="card-group">
          <div class="dt-section__head">
            <h2 class="group-title dt-title-bar">{{ Number(mainGroup.mainBpm) }}</h2>
              </div>
          <div v-for="(subItem, subIndex) in mainGroup.subBpmList" :key="subIndex" class="sub-bpm-row">
            <div class="content-wrapper">
              <div class="sub-bpm-label">{{ subItem.subBpm }}</div>
              <div class="card-grid" :style="getGridStyle()">
                <bpmCard
                  v-for="(item, idx) in subItem.contentList"
                  :key="idx"
                  :chart-info="item" :song-name="songNameOf(item)" @click="openSong(songKeyOf(item))"
                />
              </div>
            </div>
          </div>
        </section>
      </div>
    </div>
  </div>
</template>

<script setup>
import { useOpenSong } from '../../api/openSong.js'
const openSong = useOpenSong()
import { ref, onMounted, onUnmounted, computed, watch } from 'vue'
import bpmCard from '../../components/cards/bpmCard.vue'
import { getBPM } from '../../api/bpm.js'
import { loadInfos } from '../../api/infos.js'
import { setAnchorNav, clearAnchorNav } from '../../composables/useAnchorNav.js'

const bpmList = ref([])
// 曲目键名 → 显示名，卡片挂不可见曲名用（BPM 数据里只有曲绘地址，没有曲名）
const songNames = ref({})

const parseBpmData = (rawData) => {
  if (!Array.isArray(rawData)) return []
  return rawData.map(item => {
    const [mainBpm, subBpmObj] = item
    const subBpmList = Object.entries(subBpmObj).map(([subBpm, contentList]) => ({
      subBpm,
      contentList
    }))
    return {
      mainBpm: Number(mainBpm),
      subBpmList
    }
  })
}

const columns = ref(6)
const gap = ref(0.2)
const gridWidth = ref('100%')

const containerStyle = computed(() => {
  return {
    width: typeof gridWidth.value === 'number' ? `${gridWidth.value}px` : gridWidth.value,
    margin: '0 auto',
    boxSizing: 'border-box'
  }
})

const getGridStyle = () => {
  return {
    '--column-count': columns.value,
    '--gap-rem': `${gap.value}rem`
  }
}

const sortedCardList = computed(() => {
  const sortedGroups = [...bpmList.value].sort((a, b) => {
    const numA = Number(a.mainBpm)
    const numB = Number(b.mainBpm)
    return numB - numA
  })
  return sortedGroups.map(group => ({
    ...group,
    subBpmList: [...group.subBpmList].sort((a, b) => {
      const numA = Number(a.subBpm.replace('x', ''))
      const numB = Number(b.subBpm.replace('x', ''))
      return numA - numB
    })
  }))
})

onMounted(async () => {
  try {
    const [rawBpmData, infos] = await Promise.all([
      getBPM(),
      loadInfos().catch(() => ({}))
    ])
    bpmList.value = parseBpmData(rawBpmData)

    const names = {}
    for (const [key, info] of Object.entries(infos || {})) {
      if (info?.name) names[key] = info.name
    }
    songNames.value = names
  } catch (error) {
    console.error('BPM列表加载失败：', error)
  }
})

// 每个主 BPM 登记成一个锚点
watch(
  sortedCardList,
  (list) => {
    if (!list.length) {
      clearAnchorNav()
      return
    }
    setAnchorNav(
      list.map((group, index) => ({
        id: `bpm-${index}`,
        label: `${group.mainBpm}`,
        icon: 'metronome'
      }))
    )
  },
  { immediate: true }
)

onUnmounted(clearAnchorNav)

/** 该页数据里的叶子是曲绘地址，曲目键名即文件名去掉 .png */
const songKeyOf = (path) => decodeURIComponent(String(path).split("/").pop().replace(/\.png$/i, ""))

/** 曲名：查不到就退回键名，保证卡片里始终有一段可搜的文本 */
const songNameOf = (path) => {
  const key = songKeyOf(path)
  return songNames.value[key] || key
}
</script>

