  box-sizing: border-box;
  user-select: none;
}

/* 主 BPM 当分组标题用，和定数列表同一个节奏 */
.group-title {
  font-family: var(--dt-font-family-display);
  font-size: 0.16rem;
  line-height: 1;
  color: var(--dt-text);
}

.sub-bpm-row {
  width: 100%;
  margin-bottom: 0.12rem;
  box-sizing: border-box;
  user-select: none;
}

.content-wrapper {
  display: flex;
  align-items: stretch;
  width: 100%;
  box-sizing: border-box;
  min-height: 0.8rem;
  background: var(--dt-bg-layer-1);
  border: 1px solid var(--dt-border);
  border-radius: var(--dt-radius-md);
  overflow: hidden;
}

/* 变速倍率竖排贴在左边，当行标签 */
.sub-bpm-label {
  width: 0.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0.08rem;
  background: var(--dt-bg-layer-2);
  color: var(--dt-text-muted);
  border-right: 1px solid var(--dt-border);
  font-size: var(--dt-font-size-sm);
